def digest(path):
    with Path(path).open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def ref(path, expected=None):
    path = Path(path)
    if not path.is_file():
        issues.append({'path':str(path),'problem':'required retained file missing'})
        return {'path':str(path),'exists':False}
    result = {'path':str(path),'sha256':digest(path),'bytes':path.stat().st_size}
    if expected is not None:
        result['matches_recorded_sha256'] = result['sha256'] == expected
        if not result['matches_recorded_sha256']:
            issues.append({'path':str(path),'problem':'recorded file hash differs','expected':expected,'actual':result['sha256']})
    return result


def receipt(label, path):
    path = Path(path)
    body = path.read_bytes()
    data = json.loads(body)
    sha = hashlib.sha256(body).hexdigest()
    snapshot = SNAPSHOTS / (label+'-'+sha+'.json')
    if snapshot.exists():
        assert snapshot.read_bytes() == body
    else:
        snapshot.write_bytes(body)
    return data, {'path':str(path),'sha256_at_read':sha,'bytes_at_read':len(body),'immutable_snapshot':str(snapshot),'snapshot_sha256':sha}


def junit(path):
    path = Path(path)
    if path.stat().st_size > 64*1024*1024:
        raise ValueError('JUnit budget')
    root = ET.fromstring(path.read_bytes())
    cases = list(root.iter('testcase'))
    failed = sum(case.find('failure') is not None for case in cases)
    errors = sum(case.find('error') is not None for case in cases)
    skipped = sum(case.find('skipped') is not None for case in cases)
    return {'tests':len(cases),'passed':len(cases)-failed-errors-skipped,'failures':failed,'errors':errors,'skipped':skipped,'evidence':ref(path)}


